WITH enriched AS (SELECT *, SUM(monthly_fee) OVER (PARTITION BY plan, status ORDER BY end_date, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_monthly_fee, LAG(monthly_fee, 1) OVER w_part AS prev_monthly_fee, NTILE(4) OVER (PARTITION BY status ORDER BY monthly_fee, id) AS monthly_fee_bucket FROM subscriptions WINDOW w_part AS (PARTITION BY plan ORDER BY start_date, id)) SELECT DATE_TRUNC('QUARTER', end_date) AS quarter_start, SIZE(COLLECT_SET(plan)) AS num_plans, COUNT(CASE WHEN status = 'EXPIRED' THEN 1 END) AS expired_count, MIN(cumulative_monthly_fee) AS min_cumulative_monthly_fee, COUNT(*) AS cnt, COUNT_IF(plan = 'basic') AS basic_events, COUNT_IF(status = 'EXPIRED') AS expired_events FROM enriched GROUP BY DATE_TRUNC('QUARTER', end_date) ORDER BY num_plans
